begin;


set local role authenticated;
do $$
declare n integer;
begin
  perform set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
  select count(*) into n from storage.objects where bucket_id='assignment-files';
  if n<>1 then raise exception 'linked parent saw unrelated class, old-year, or cross-school assignment files'; end if;
  if not exists(select 1 from storage.objects where name='10000000-0000-0000-0000-000000000001/22000000-0000-0000-0000-000000000001/file.pdf') then
    raise exception 'linked parent could not read the current active child assignment file';
  end if;

  perform set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',true);
  select count(*) into n from storage.objects where bucket_id='assignment-files';
  if n<>0 then raise exception 'disabled parent membership read assignment files'; end if;

  perform set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
  select count(*) into n from storage.objects where bucket_id='assignment-files';
  if n<>1 then raise exception 'linked parent could not read the same-school assignment for their active child'; end if;
end;
$$;

reset role;
set local role anon;
do $$
declare n integer;
begin
  select count(*) into n from storage.objects where bucket_id='assignment-files';
  if n<>0 then raise exception 'anonymous user read private assignment files'; end if;
end;
$$;
reset role;
rollback;
